@namespace sv_30b8c8b1cce4461bbd3c62b9a7cb28a0.Components.Pages.Apply

<fieldset class="reference-entry">
    <legend>Reference @(Index + 1)</legend>

    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-group">
        <label for="ref-name-@Index">Name</label>
        <input id="ref-name-@Index" type="text" value="@Entry.Name"
               @onchange="e => Update(Entry with { Name = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label for="ref-rel-@Index">Relationship</label>
        <input id="ref-rel-@Index" type="text" value="@Entry.Relationship"
               @onchange="e => Update(Entry with { Relationship = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label for="ref-email-@Index">Email</label>
        <input id="ref-email-@Index" type="email" value="@Entry.Email"
               @onchange="e => Update(Entry with { Email = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label for="ref-phone-@Index">Phone</label>
        <input id="ref-phone-@Index" type="tel" value="@Entry.Phone"
               @onchange="e => Update(Entry with { Phone = (string?)e.Value ?? string.Empty })" />
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public ReferenceModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<ReferenceModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void Update(ReferenceModel updated)
    {
        OnChanged.InvokeAsync(updated);
    }

    public record ReferenceModel
    {
        public string Name { get; init; } = string.Empty;
        public string Relationship { get; init; } = string.Empty;
        public string Email { get; init; } = string.Empty;
        public string Phone { get; init; } = string.Empty;
    }
}

