<section class="step-panel">
    <h2>References</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="@Entries[index]"
                       Index="@index"
                       CanRemove="@(Entries.Count > 2)"
                       OnChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    @if (Entries.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Reference</button>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter] public List<ReferenceForm.ReferenceModel> Entries { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<ReferenceForm.ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (Entries.Count < 2)
        {
            while (Entries.Count < 2)
            {
                Entries.Add(new ReferenceForm.ReferenceModel());
            }
        }
    }

    private void AddEntry()
    {
        if (Entries.Count < 3)
        {
            Entries.Add(new ReferenceForm.ReferenceModel());
            StateHasChanged();
        }
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 2)
        {
            Entries.RemoveAt(index);
            StateHasChanged();
        }
    }

    private void UpdateEntry(int index, ReferenceForm.ReferenceModel updated)
    {
        Entries[index] = updated;
        StateHasChanged();
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Name) || string.IsNullOrWhiteSpace(entry.Email))
            {
                ErrorMessage = "Each reference requires at least a name and email.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }
}
