<section class="step-panel">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="cover-letter">Write your cover letter</label>
        <textarea id="cover-letter" rows="12" maxlength="@MaxLength"
                  value="@Text"
                  @oninput="HandleInput">@Text</textarea>
        <span class="char-count">@Text.Length / @MaxLength characters</span>
    </div>

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter] public string Text { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;

    private void HandleInput(ChangeEventArgs e)
    {
        var value = (string?)e.Value ?? string.Empty;
        Text = value.Length > MaxLength ? value[..MaxLength] : value;
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(Text);
    }
}
