1. @namespace sv_30b8c8b1cce4461bbd3c62b9a7cb28a0.Components.Apply
2. 
3. <fieldset class="work-entry">
4.     <legend>Position @(Index + 1)</legend>
5. 
6.     @if (CanRemove)
7.     {
8.         <button type="button" class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
9.     }
10. 
11.     <div class="form-group">
12.         <label for="company-@Index">Company Name</label>
13.         <input id="company-@Index" type="text" value="@Entry.Company"
14.                @onchange="e => Update(Entry with { Company = (string?)e.Value ?? string.Empty })" />
15.     </div>
16. 
17.     <div class="form-group">
18.         <label for="title-@Index">Job Title</label>
19.         <input id="title-@Index" type="text" value="@Entry.Title"
20.                @onchange="e => Update(Entry with { Title = (string?)e.Value ?? string.Empty })" />
21.     </div>
22. 
23.     <div class="form-group">
24.         <label for="start-@Index">Start Date</label>
25.         <input id="start-@Index" type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
26.                @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
27.     </div>
28. 
29.     <div class="form-group">
30.         <label>
31.             <input type="checkbox" checked="@IsCurrent"
32.                    @onchange="e => HandleCurrentChanged((bool)(e.Value ?? false))" />
33.             I currently work here
34.         </label>
35.     </div>
36. 
37.     @if (!IsCurrent)
38.     {
39.         <div class="form-group">
40.             <label for="end-@Index">End Date</label>
41.             <input id="end-@Index" type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)"
42.                    @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
43.         </div>
44.     }
45. 
46.     <div class="form-group">
47.         <label for="desc-@Index">Description</label>
48.         <textarea id="desc-@Index" rows="3" @onchange="e => Update(Entry with { Description = (string?)e.Value ?? string.Empty })">@Entry.Description</textarea>
49.     </div>
50. </fieldset>
51. 
52. @code {
53.     [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
54.     [Parameter] public int Index { get; set; }
55.     [Parameter] public bool CanRemove { get; set; }
56.     [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
57.     [Parameter] public EventCallback OnRemove { get; set; }
58. 
59.     private bool IsCurrent => Entry.IsCurrent;
60. 
61.     private void HandleCurrentChanged(bool isCurrent)
62.     {
63.         var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
64.         Update(updated);
65.     }
66. 
67.     private void Update(WorkEntryModel updated)
68.     {
69.         OnChanged.InvokeAsync(updated);
70.     }
71. 
72.     public record WorkEntryModel
