@namespace sv_30b8c8b1cce4461bbd3c62b9a7cb28a0.Components.Apply

<fieldset class="work-entry">
    <legend>Position @(Index + 1)</legend>

    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-group">
        <label for="company-@Index">Company Name</label>
        <input id="company-@Index" type="text" value="@Entry.Company"
               @onchange="OnCompanyChanged" />
    </div>

    <div class="form-group">
        <label for="title-@Index">Job Title</label>
        <input id="title-@Index" type="text" value="@Entry.Title"
               @onchange="OnTitleChanged" />
    </div>

    <div class="form-group">
        <label for="start-@Index">Start Date</label>
        <input id="start-@Index" type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
               @onchange="OnStartDateChanged" />
    </div>

    <div class="form-group">
        <label>
            <input type="checkbox" checked="@IsCurrent"
                   @onchange="OnCurrentChanged" />
            I currently work here
        </label>
    </div>

    @if (!IsCurrent)
    {
        <div class="form-group">
            <label for="end-@Index">End Date</label>
            <input id="end-@Index" type="date" value="@EndDateValue"
                   @onchange="OnEndDateChanged" />
        </div>
    }

    <div class="form-group">
        <label for="desc-@Index">Description</label>
        <textarea id="desc-@Index" rows="3" @onchange="OnDescriptionChanged">@Entry.Description</textarea>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;
    private string EndDateValue => Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty;

    private void OnCompanyChanged(ChangeEventArgs e) =>
        Update(Entry with { Company = (string?)e.Value ?? string.Empty });

    private void OnTitleChanged(ChangeEventArgs e) =>
        Update(Entry with { Title = (string?)e.Value ?? string.Empty });

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        if (DateTime.TryParse(val, out var date))
            Update(Entry with { StartDate = date });
    }

    private void OnEndDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        var endDate = string.IsNullOrEmpty(val) ? (DateTime?)null : DateTime.Parse(val);
        Update(Entry with { EndDate = endDate });
    }

    private void OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        Update(Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
    }

    private void OnDescriptionChanged(ChangeEventArgs e) =>
        Update(Entry with { Description = (string?)e.Value ?? string.Empty });

    private void Update(WorkEntryModel updated) =>
        OnChanged.InvokeAsync(updated);

    public record WorkEntryModel
    {
        public string Company { get; init; } = string.Empty;
        public string Title { get; init; } = string.Empty;
        public DateTime StartDate { get; init; } = DateTime.Today;
        public DateTime? EndDate { get; init; }
        public bool IsCurrent { get; init; }
        public string Description { get; init; } = string.Empty;
    }
}

