arguments.file_text:
namespace sv_274c299c071b4a5b84efd5e141edeb88.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_274c299c071b4a5b84efd5e141edeb88.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <button class="step @stepClass"
                disabled="@(!IsStepClickable(stepIndex))"
                @onclick="() => OnStepClick(stepIndex)"
                aria-current="@(stepIndex == CurrentStep ? "step" : null)">
            <span class="step-number">
                @if (CompletedSteps.Contains(stepIndex))
                {
                    <span class="checkmark">✓</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@StepNames[stepIndex]</span>
        </button>
        @if (i < StepNames.Count - 1)
        {
            <span class="step-connector @(CompletedSteps.Contains(stepIndex) ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "current";
        if (CompletedSteps.Contains(step)) return "completed";
        return "future";
    }

    private bool IsStepClickable(int step) => CompletedSteps.Contains(step) && step != CurrentStep;

    private async Task OnStepClick(int step)
    {
        if (IsStepClickable(step))
            await OnStepSelected.InvokeAsync(step);
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    background: none;
    border: none;
    cursor: default;
    padding: 0.5rem 1rem;
    transition: opacity 0.2s;
}

.step:not(:disabled) {
    cursor: pointer;
}

.step:not(:disabled):hover .step-number {
    transform: scale(1.1);
}

.step-number {
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    transition: all 0.2s;
}

.step-label {
    font-size: 0.8rem;
    white-space: nowrap;
}

.step.current .step-number {
    background: #2563eb;
    color: white;
}

.step.current .step-label {
    color: #2563eb;
    font-weight: 600;
}

.step.completed .step-number {
    background: #16a34a;
    color: white;
}

.step.completed .step-label {
    color: #16a34a;
}

.step.future .step-number {
    background: #e5e7eb;
    color: #9ca3af;
}

.step.future .step-label {
    color: #9ca3af;
}

.checkmark {
    font-size: 1.1rem;
}

.step-connector {
    width: 2rem;
    height: 2px;
    background: #e5e7eb;
    margin-bottom: 1.5rem;
}

.step-connector.completed {
    background: #16a34a;
}

