.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    background: none;
    border: none;
    cursor: default;
    padding: 0.5rem 1rem;
    transition: opacity 0.2s;
}

.step:not(:disabled) {
    cursor: pointer;
}

.step:not(:disabled):hover .step-number {
    transform: scale(1.1);
}

.step-number {
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    transition: all 0.2s;
}

.step-label {
    font-size: 0.8rem;
    white-space: nowrap;
}

.step.current .step-number {
    background: #2563eb;
    color: white;
}

.step.current .step-label {
    color: #2563eb;
    font-weight: 600;
}

.step.completed .step-number {
    background: #16a34a;
    color: white;
}

.step.completed .step-label {
    color: #16a34a;
}

.step.future .step-number {
    background: #e5e7eb;
    color: #9ca3af;
}

.step.future .step-label {
    color: #9ca3af;
}

.checkmark {
    font-size: 1.1rem;
}

.step-connector {
    width: 2rem;
    height: 2px;
    background: #e5e7eb;
    margin-bottom: 1.5rem;
}

.step-connector.completed {
    background: #16a34a;
}

