@namespace sv_274c299c071b4a5b84efd5e141edeb88.Components.Pages.Apply

<div class="personal-info-step">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" />
        @if (_errors.ContainsKey("FullName"))
        {
            <span class="error">@_errors["FullName"]</span>
        }
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" />
        @if (_errors.ContainsKey("Email"))
        {
            <span class="error">@_errors["Email"]</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" />
        @if (_errors.ContainsKey("Phone"))
        {
            <span class="error">@_errors["Phone"]</span>
        }
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" @bind="Address" @bind:event="oninput" rows="3"></textarea>
        @if (_errors.ContainsKey("Address"))
        {
            <span class="error">@_errors["Address"]</span>
        }
    </div>

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@_validating">
            @if (_validating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public EventCallback<string> FullNameChanged { get; set; }
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<string> AddressChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private Dictionary<string, string> _errors = new();
    private bool _validating;

    private async Task HandleNext()
    {
        _errors.Clear();

        if (string.IsNullOrWhiteSpace(FullName))
            _errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email))
            _errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone))
            _errors["Phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Address))
            _errors["Address"] = "Address is required.";

        if (_errors.Count > 0) return;

        _validating = true;
        try
        {
            var emailValid = await ValidateEmail(Email);
            if (!emailValid)
            {
                _errors["Email"] = "This email address is not valid.";
                return;
            }

            await FullNameChanged.InvokeAsync(FullName);
            await EmailChanged.InvokeAsync(Email);
            await PhoneChanged.InvokeAsync(Phone);
            await AddressChanged.InvokeAsync(Address);
            await OnNext.InvokeAsync();
        }
        finally
        {
            _validating = false;
        }
    }
}

@namespace sv_274c299c071b4a5b84efd5e141edeb88.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company *</label>
            <input type="text" value="@Entry.Company"
                   @onchange="e => UpdateEntry(Entry with { Company = e.Value?.ToString() ?? "" })" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Entry.Title"
                   @onchange="e => UpdateEntry(Entry with { Title = e.Value?.ToString() ?? "" })" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")"
                   disabled="@_isCurrent"
                   @onchange="e => UpdateEntry(Entry with { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!) })" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@_isCurrent" @onchange="HandleCurrentToggle" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => UpdateEntry(Entry with { Description = e.Value?.ToString() ?? "" })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnRemove { get; set; }

    private bool _isCurrent => Entry.EndDate is null && Entry.IsCurrent;

    private async Task UpdateEntry(WorkEntryModel updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task HandleCurrentToggle(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        await OnEntryChanged.InvokeAsync(updated);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_274c299c071b4a5b84efd5e141edeb88.Components.Pages.Apply

<div class="work-history-step">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="index"
                       ShowRemove="Entries.Count > 1"
                       OnEntryChanged="entry => HandleEntryChanged(index, entry)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (_error is not null)
    {
        <div class="error">@_error</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryForm.WorkEntryModel> Entries { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryForm.WorkEntryModel>> EntriesChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? _error;

    private async Task HandleEntryChanged(int index, WorkEntryForm.WorkEntryModel entry)
    {
        Entries[index] = entry;
        await EntriesChanged.InvokeAsync(Entries);
    }

    private async Task AddEntry()
    {
        Entries.Add(new WorkEntryForm.WorkEntryModel());
        await EntriesChanged.InvokeAsync(Entries);
    }

    private async Task RemoveEntry(int index)
    {
        Entries.RemoveAt(index);
        await EntriesChanged.InvokeAsync(Entries);
    }

    private async Task HandleNext()
    {
        _error = null;
        var first = Entries[0];
        if (string.IsNullOrWhiteSpace(first.Company) || string.IsNullOrWhiteSpace(first.Title))
        {
            _error = "At least one work entry must have a company and job title.";
            return;
        }
        await OnNext.InvokeAsync();
    }
}

@namespace sv_274c299c071b4a5b84efd5e141edeb88.Components.Pages.Apply

<div class="reference-form">
    <div class="entry-header">
        <h4>Reference @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Entry.Name"
                   @onchange="e => UpdateEntry(Entry with { Name = e.Value?.ToString() ?? "" })" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Entry.Relationship"
                   @onchange="e => UpdateEntry(Entry with { Relationship = e.Value?.ToString() ?? "" })" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Entry.Email"
                   @onchange="e => UpdateEntry(Entry with { Email = e.Value?.ToString() ?? "" })" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Entry.Phone"
                   @onchange="e => UpdateEntry(Entry with { Phone = e.Value?.ToString() ?? "" })" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Entry { get; set; } = default!;
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<ReferenceModel> OnEntryChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnRemove { get; set; }

    private async Task UpdateEntry(ReferenceModel updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    public record ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_274c299c071b4a5b84efd5e141edeb88.Components.Pages.Apply

<div class="references-step">
    <h2>References</h2>
    <p class="hint">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="References[index]"
                       Index="index"
                       ShowRemove="References.Count > 2"
                       OnEntryChanged="entry => HandleChanged(index, entry)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (_error is not null)
    {
        <div class="error">@_error</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceForm.ReferenceModel> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<ReferenceForm.ReferenceModel>> ReferencesChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? _error;

    private async Task HandleChanged(int index, ReferenceForm.ReferenceModel entry)
    {
        References[index] = entry;
        await ReferencesChanged.InvokeAsync(References);
    }

    private async Task AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceForm.ReferenceModel());
            await ReferencesChanged.InvokeAsync(References);
        }
    }

    private async Task RemoveReference(int index)
    {
        References.RemoveAt(index);
        await ReferencesChanged.InvokeAsync(References);
    }

    private async Task HandleNext()
    {
        _error = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
            {
                _error = "Each reference must have a name, relationship, and email.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }
}

@namespace sv_274c299c071b4a5b84efd5e141edeb88.Components.Pages.Apply

<div class="cover-letter-step">
