<div class="work-history-step">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="index"
                       ShowRemove="Entries.Count > 1"
                       OnEntryChanged="entry => HandleEntryChanged(index, entry)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (_error is not null)
    {
        <div class="error">@_error</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryForm.WorkEntryModel> Entries { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryForm.WorkEntryModel>> EntriesChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? _error;

    private async Task HandleEntryChanged(int index, WorkEntryForm.WorkEntryModel entry)
    {
        Entries[index] = entry;
        await EntriesChanged.InvokeAsync(Entries);
    }

    private async Task AddEntry()
    {
        Entries.Add(new WorkEntryForm.WorkEntryModel());
        await EntriesChanged.InvokeAsync(Entries);
    }

    private async Task RemoveEntry(int index)
    {
        Entries.RemoveAt(index);
        await EntriesChanged.InvokeAsync(Entries);
    }

    private async Task HandleNext()
    {
        _error = null;
        var first = Entries[0];
        if (string.IsNullOrWhiteSpace(first.Company) || string.IsNullOrWhiteSpace(first.Title))
        {
            _error = "At least one work entry must have a company and job title.";
            return;
        }
        await OnNext.InvokeAsync();
    }
}
