+        await ReferencesChanged.InvokeAsync(References);
+    }
+
+    private async Task HandleNext()
+    {
+        _error = null;
+        foreach (var r in References)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
+            {
+                _error = "Each reference must have a name, relationship, and email.";
+                return;
+            }
+        }
+        await OnNext.InvokeAsync();
+    }
+}
+

