@page "/apply"
@namespace sv_274c299c071b4a5b84efd5e141edeb88.Components.Pages.Apply
@using sv_274c299c071b4a5b84efd5e141edeb88.Models
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="_currentStep"
                   CompletedSteps="_completedSteps"
                   OnStepSelected="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@_fullName" FullNameChanged="v => _fullName = v"
                              Email="@_email" EmailChanged="v => _email = v"
                              Phone="@_phone" PhoneChanged="v => _phone = v"
                              Address="@_address" AddressChanged="v => _address = v"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             EntriesChanged="entries => _workEntries = entries"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="_references"
                            ReferencesChanged="refs => _references = refs"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             CoverLetterChanged="v => _coverLetter = v"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep FullName="@_fullName" Email="@_email"
                        Phone="@_phone" Address="@_address"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="@_coverLetter"
                        OnEditSection="GoToStep"
                        OnBack="PreviousStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private HashSet<int> _completedSteps = new();

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> _workEntries = new() { new() };

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> _references = new() { new(), new() };

    // Step 4 state
    private string _coverLetter = "";

    private void NextStep()
    {
        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private async Task<int> SubmitApplication()
    {
        var personal = new PersonalInfo(_fullName, _email, _phone, _address);

        var workHistory = new WorkHistory(
            _workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.EndDate, e.Description
            )).ToList()
        );

        var references = _references.Select(r => new Reference(
            r.Name, r.Relationship, r.Email, r.Phone
        )).ToList();

        var application = new JobApplication(personal, workHistory, references, _coverLetter);
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

