@namespace sv_274c299c071b4a5b84efd5e141edeb88.Components.Pages.Apply

<div class="reference-form">
    <div class="entry-header">
        <h4>Reference @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Entry.Name" @onchange="OnNameChanged" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Entry.Relationship" @onchange="OnRelationshipChanged" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Entry.Email" @onchange="OnEmailChanged" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Entry.Phone" @onchange="OnPhoneChanged" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Entry { get; set; } = default!;
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<ReferenceModel> OnEntryChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnRemove { get; set; }

    private Task OnNameChanged(ChangeEventArgs e)
    {
        Entry.Name = e.Value?.ToString() ?? "";
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task OnRelationshipChanged(ChangeEventArgs e)
    {
        Entry.Relationship = e.Value?.ToString() ?? "";
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task OnEmailChanged(ChangeEventArgs e)
    {
        Entry.Email = e.Value?.ToString() ?? "";
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task OnPhoneChanged(ChangeEventArgs e)
    {
        Entry.Phone = e.Value?.ToString() ?? "";
        return OnEntryChanged.InvokeAsync(Entry);
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

